  const diff = Date.now() - new Date(isoString).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 60) return mins <= 1 ? "just now" : `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  return days === 1 ? "yesterday" : `${days} days ago`;
}

function Dashboard({ onNavigate }) {
  const today = new Date().toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" });
  const { recents, runningSet } = usePipelineSnapshot();

  const handleNavigate = useCallback((target) => {
    onNavigate(target);
  }, [onNavigate]);

  return (
    <div data-screen-label="Dashboard">
      <header className="page-header">
        <div>
          <h1 className="page-title">Dashboard</h1>
          <p className="page-subtitle">{today} · 4 active stages · last run 12 minutes ago</p>
        </div>
        <button className="btn btn-primary">
          <Icon.Plus size={14} />
          New Video
        </button>
      </header>

      <button
        className="brain-banner"
        onClick={() => handleNavigate("brain")}
        aria-label="Open Knowledge Brain"
      >
        <div className="brain-banner-icon">
          <Icon.Brain size={32} />
        </div>
        <div className="brain-banner-text">
          <div className="brain-banner-eyebrow">Knowledge Brain</div>
          <div className="brain-banner-title">The Brain</div>
          <div className="brain-banner-tagline">Feed me — and I'll spit analysis.</div>
        </div>
        <div className="brain-banner-stats">
          <div className="brain-banner-stat">
            <span className="brain-banner-stat-value">142</span>
            <span className="brain-banner-stat-label">decoded</span>
          </div>
          <div className="brain-banner-stat">
            <span className="brain-banner-stat-value">8.1</span>
            <span className="brain-banner-stat-label">avg hook /10</span>
          </div>
          <div className="brain-banner-stat">
            <span className="brain-banner-stat-value">37</span>
            <span className="brain-banner-stat-label">techniques saved</span>
          </div>
        </div>
        <div className="brain-banner-cta">
          <span>Drop something in</span>
          <Icon.ArrowRight size={16} />
        </div>
        <div className="brain-banner-orb brain-banner-orb-1" aria-hidden="true" />
        <div className="brain-banner-orb brain-banner-orb-2" aria-hidden="true" />
      </button>

      <div className="dash-grid">
        {CARD_DEFS.map((card) => {
          const IconCmp = Icon[card.icon];
          const items = recents[card.id] || [];
          const running = runningSet.has(card.id);
          return (
            <div
              key={card.id}
              className={"dash-card" + (running ? " running" : "")}
              style={{ "--stage-color": card.color, fontWeight: "600", fontFamily: "Inter", backgroundColor: "rgb(26, 30, 38)" }}
              onClick={() => {
                if (card.id === "outline") {
                  window.location.hash = "distribution/outline";
                  handleNavigate("distribution");
                } else {
                  handleNavigate(card.id);
                }
              }}>

              <div className="dash-card-header">
                <div className="dash-card-icon"><IconCmp size={18} /></div>
                <div style={{ flex: 1 }}>
                  <div className="dash-card-name">{card.name}</div>
                </div>
                <div className="dash-card-open">
                  {running ?
                    <span className="nav-status running" style={{ width: 8, height: 8 }} /> :
                    <Icon.ArrowRight size={14} />
                  }
                </div>
              </div>

              <ul className="activity-list">
                {items.length === 0 ? (
                  <li className="activity-item" style={{ color: "var(--text-muted)" }}>No recent files</li>
                ) : items.map((item, i) => (
                  <li key={i} className="activity-item">
                    <span className="activity-text">{item.name}</span>
                    <span className="activity-time">{formatRelative(item.modified)}</span>
                  </li>
                ))}
              </ul>

              <button
                className="btn-stage"
                style={{ "--stage-color": card.color }}
                onClick={(e) => {
                  e.stopPropagation();
                  if (card.id === "outline") {
                    window.location.hash = "distribution/outline";
                    handleNavigate("distribution");
                  } else {
                    handleNavigate(card.id);
                  }
                }}>
                <Icon.Play size={12} />
                {card.cta}
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default Dashboard;

/* ============================================================
   Content Hub — Design Tokens
   ============================================================ */

:root {
  /* Surfaces */
  --bg-base: #0D0F12;
  --bg-surface: #13161B;
  --bg-elevated: #1A1E26;
  --bg-elevated-hover: #1F242E;

  /* Borders */
  --border: #252932;
  --border-active: #3A4152;

  /* Text */
  --text-primary: #F0F2F5;
  --text-secondary: #7A8394;
  --text-muted: #4A5366;

  /* Brand */
  --accent: #5B8DEF;
  --accent-glow: #5B8DEF22;
  --accent-strong: #7AA3F5;

  /* Semantic */
  --success: #3DD68C;
  --warning: #F5A623;
  --danger: #E5534B;

  /* Stage identities */
  --stage-trends: #F5A623;
  --stage-research: #5B8DEF;
  --stage-ideation: #A855F7;
  --stage-hooks: #EC4899;
  --stage-title: #F97316;
  --stage-outline: #14B8A6;
  --stage-distribution: #3DD68C;
  --brain: #06B6D4;

  /* Radii */
  --r-card: 12px;
  --r-input: 8px;
  --r-button: 6px;
  --r-pill: 4px;
  --r-avatar: 8px;

  /* Type */
  --font-ui: "Inter", system-ui, -apple-system, sans-serif;
  --font-mono: "Geist Mono", "JetBrains Mono", ui-monospace, monospace;

  /* Page accent — set per view by app.jsx, drives particles + ambient gradient */
  --page-accent: #5B8DEF;
}

/* ============================================================
   Reset / Base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; }
html, body, #root { height: 100%; }
html { background: var(--bg-base); }
body {
  margin: 0;
  font-family: var(--font-ui);
  background: transparent;
  color: var(--text-primary);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow: hidden;
  position: relative;
}

/* Ambient page gradient — sits above body bg + particle canvas, below content.
   Picks up --page-accent and transitions smoothly when the view changes. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    radial-gradient(70% 60% at 15% 0%,
      color-mix(in oklab, var(--page-accent) 26%, transparent) 0%,
      transparent 60%),
    radial-gradient(55% 60% at 100% 100%,
      color-mix(in oklab, var(--page-accent) 18%, transparent) 0%,
      transparent 55%),
    radial-gradient(40% 40% at 80% 20%,
      color-mix(in oklab, var(--page-accent) 10%, transparent) 0%,
      transparent 60%);
  transition: background 600ms ease;
}

/* Vignette glow on the edges so the field doesn't feel flat */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background: radial-gradient(
    120% 100% at 50% 50%,
    transparent 55%,
    color-mix(in oklab, var(--page-accent) 8%, transparent) 85%,
    color-mix(in oklab, var(--page-accent) 14%, transparent) 100%
  );
  mix-blend-mode: screen;
  transition: background 600ms ease;
}
button { font-family: inherit; cursor: pointer; }
button:focus-visible, input:focus-visible, textarea:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 10px;
  border: 2px solid var(--bg-base);
}
::-webkit-scrollbar-thumb:hover { background: var(--border-active); }

/* ============================================================
   App shell
   ============================================================ */
.app {
  display: grid;
  grid-template-columns: var(--sidebar-w, 240px) 1fr;
  height: 100vh;
  transition: grid-template-columns 200ms cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  z-index: 2;
}
.app.collapsed { --sidebar-w: 56px; }

.main {
  overflow-y: auto;
  overflow-x: hidden;
  background: transparent;
  position: relative;
  z-index: 2;
}
.main-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 32px 40px 64px;
}

/* ============================================================
   Sidebar
   ============================================================ */
.sidebar {
  background: linear-gradient(180deg,
    color-mix(in oklab, var(--page-accent) 10%, var(--bg-surface)) 0%,
    var(--bg-surface) 40%,
    var(--bg-surface) 100%);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  position: relative;
  transition: background 600ms ease;
}

/* Sidebar starfield — ambient twinkling dots behind the nav */
.sidebar::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 18% 8%,  color-mix(in oklab, var(--page-accent) 80%, transparent) 0.8px, transparent 1.6px),
    radial-gradient(circle at 72% 14%, color-mix(in oklab, var(--page-accent) 60%, transparent) 0.6px, transparent 1.2px),
    radial-gradient(circle at 38% 32%, color-mix(in oklab, var(--page-accent) 70%, transparent) 0.7px, transparent 1.4px),
    radial-gradient(circle at 82% 44%, color-mix(in oklab, var(--page-accent) 90%, transparent) 0.9px, transparent 1.8px),
    radial-gradient(circle at 22% 62%, color-mix(in oklab, var(--page-accent) 60%, transparent) 0.6px, transparent 1.2px),
    radial-gradient(circle at 65% 76%, color-mix(in oklab, var(--page-accent) 80%, transparent) 0.8px, transparent 1.6px),
    radial-gradient(circle at 12% 88%, color-mix(in oklab, var(--page-accent) 70%, transparent) 0.7px, transparent 1.4px);
  background-size: 300px 420px;
  background-repeat: repeat;
  opacity: 0.7;
  pointer-events: none;
  z-index: 0;
  animation: skyDrift 90s linear infinite, skyTwinkle 5s ease-in-out infinite;
}
/* Soft top-light bloom in the sidebar */
.sidebar::after {
  content: "";
  position: absolute;
  top: -80px;
  left: -40px;
  right: -40px;
  height: 240px;
  background: radial-gradient(60% 100% at 50% 100%,
    color-mix(in oklab, var(--page-accent) 30%, transparent) 0%,
    transparent 70%);
  filter: blur(20px);
  pointer-events: none;
  z-index: 0;
  transition: background 600ms ease;
}
@keyframes skyDrift {
  from { background-position: 0 0; }
  to   { background-position: 300px 420px; }
}
@keyframes skyTwinkle {
  0%, 100% { filter: brightness(0.85); }
  50%      { filter: brightness(1.2); }
}

/* Sidebar inner content sits above the starfield */
.sidebar > * { position: relative; z-index: 1; }
.sidebar-brand {
  height: 56px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 16px;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}
.brand-mark {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
