}
.app.collapsed .sidebar-section-label,
.app.collapsed .brand-text,
.app.collapsed .nav-label,
.app.collapsed .nav-status,
.app.collapsed .sidebar-bottom-label { display: none; }

.sidebar-nav {
  display: flex;
  flex-direction: column;
  padding: 0 8px;
}
.nav-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
