  overflow: hidden;
}

/* Glow halo behind each nav item */
.nav-item::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: var(--r-button);
  background:
    radial-gradient(70% 130% at 12% 50%,
      color-mix(in oklab, var(--stage-color, var(--page-accent)) 32%, transparent) 0%,
      transparent 70%),
    radial-gradient(50% 100% at 90% 50%,
      color-mix(in oklab, var(--stage-color, var(--page-accent)) 16%, transparent) 0%,
      transparent 70%);
  opacity: 0;
  transition: opacity 280ms ease;
  pointer-events: none;
  z-index: 0;
}
.nav-item:hover::before { opacity: 1; }
.nav-item.active::before { opacity: 0.85; }

/* Twinkling constellation across each tab name */
.nav-item::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 18% 28%, color-mix(in oklab, var(--stage-color, var(--page-accent)) 95%, white) 0.6px, transparent 1.2px),
    radial-gradient(circle at 42% 70%, color-mix(in oklab, var(--stage-color, var(--page-accent)) 80%, white) 0.5px, transparent 1px),
    radial-gradient(circle at 60% 32%, color-mix(in oklab, var(--stage-color, var(--page-accent)) 90%, white) 0.7px, transparent 1.4px),
    radial-gradient(circle at 78% 64%, color-mix(in oklab, var(--stage-color, var(--page-accent)) 75%, white) 0.5px, transparent 1px),
    radial-gradient(circle at 92% 30%, color-mix(in oklab, var(--stage-color, var(--page-accent)) 100%, white) 0.8px, transparent 1.6px);
  opacity: 0;
  pointer-events: none;
  z-index: 1;
  transition: opacity 320ms ease;
  filter: drop-shadow(0 0 4px color-mix(in oklab, var(--stage-color, var(--page-accent)) 60%, transparent));
}
.nav-item:hover::after,
.nav-item.active::after {
  opacity: 1;
  animation: navTwinkle 3.2s ease-in-out infinite;
}
@keyframes navTwinkle {
  0%, 100% { opacity: 0.55; transform: translateX(0); }
  50%      { opacity: 1;    transform: translateX(2px); }
}

/* Lift nav item content above the glow/stars */
.nav-item > * { position: relative; z-index: 2; }

.nav-item:hover { background: color-mix(in oklab, var(--stage-color, var(--page-accent)) 8%, var(--bg-elevated)); }
.nav-item.active {
  background: color-mix(in oklab, var(--stage-color, var(--accent)) 12%, var(--bg-elevated));
  border-left-color: var(--stage-color, var(--accent));
  box-shadow: inset 0 0 24px -6px color-mix(in oklab, var(--stage-color, var(--accent)) 35%, transparent);
}
.nav-item.active .nav-label {
  color: var(--stage-color, var(--accent));
  font-weight: 500;
}
.nav-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  color: var(--stage-color, var(--text-secondary));
  display: grid;
  place-items: center;
}
.nav-label {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
}
.nav-status {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.nav-status.idle {
  border: 1.5px solid var(--text-muted);
  background: transparent;
}
.nav-status.done {
  background: var(--success);
  box-shadow: 0 0 6px var(--success);
}
.nav-status.running {
  background: var(--warning);
  animation: pulse 1.5s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { box-shadow: 0 0 0 0 var(--warning); opacity: 1; }
  50% { box-shadow: 0 0 0 6px transparent; opacity: 0.7; }
}

.sidebar-divider {
  height: 1px;
  background: var(--border);
  margin: 12px 16px;
}
.app.collapsed .sidebar-divider { margin: 12px 8px; }

.sidebar-bottom {
  margin-top: auto;
  padding: 12px 8px 16px;
  border-top: 1px solid var(--border);
}
.collapse-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 12px;
  background: transparent;
  border: none;
  color: var(--text-muted);
  border-radius: var(--r-button);
  font-size: 13px;
  margin-top: 4px;
}
.collapse-toggle:hover { background: var(--bg-elevated); color: var(--text-secondary); }
.collapse-toggle .chevron-icon {
  transition: transform 200ms ease;
}
.app.collapsed .collapse-toggle .chevron-icon {
  transform: rotate(180deg);
}

/* Collapsed: center icons */
.app.collapsed .sidebar-brand { justify-content: center; padding: 0; }
.app.collapsed .nav-item { justify-content: center; padding: 8px 0; border-left: none; }
.app.collapsed .nav-item.active {
  background: var(--bg-elevated);
  position: relative;
}
.app.collapsed .nav-item.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 6px;
  bottom: 6px;
  width: 2px;
  background: var(--stage-color, var(--accent));
  border-radius: 0 2px 2px 0;
}
.app.collapsed .collapse-toggle { justify-content: center; }

/* Tooltip on collapsed hover */
.nav-tooltip {
  position: absolute;
  left: calc(100% + 8px);
  top: 50%;
  transform: translateY(-50%);
  background: var(--bg-elevated);
  border: 1px solid var(--border-active);
  color: var(--text-primary);
  padding: 6px 10px;
  border-radius: var(--r-button);
  font-size: 12px;
  white-space: nowrap;
  z-index: 1000;
