}
.stage-banner-orb-1 {
  width: 200px;
  height: 200px;
  background: color-mix(in oklab, var(--stage-color) 50%, transparent);
  top: -120px;
  left: -40px;
}
.stage-banner-orb-2 {
  width: 160px;
  height: 160px;
  background: color-mix(in oklab, var(--stage-color) 30%, transparent);
  bottom: -110px;
  right: 18%;
}

/* Back button sits next to icon block */
.stage-banner .back-btn {
  margin-right: 4px;
  background: var(--bg-elevated);
}

/* ============================================================
   Page header
   ============================================================ */
.page-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
}
.page-title {
  font-size: 24px;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0 0 4px;
  letter-spacing: -0.01em;
}
.page-subtitle {
  font-size: 14px;
  color: var(--text-secondary);
  margin: 0;
}

/* ============================================================
   Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 14px;
  border-radius: var(--r-button);
  font-size: 13px;
  font-weight: 500;
  border: 1px solid transparent;
  transition: background 80ms ease, border-color 80ms ease, color 80ms ease;
  background: transparent;
  color: var(--text-primary);
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: white;
}
.btn-primary:hover { background: var(--accent-strong); }
.btn-ghost {
  border-color: var(--border);
  color: var(--text-secondary);
  background: var(--bg-surface);
}
.btn-ghost:hover { border-color: var(--border-active); color: var(--text-primary); }
.btn-icon {
  width: 32px;
  height: 32px;
  padding: 0;
  display: grid;
  place-items: center;
  color: var(--text-secondary);
  border-radius: var(--r-button);
  background: transparent;
  border: 1px solid transparent;
}
.btn-icon:hover { background: var(--bg-elevated); color: var(--text-primary); }

.btn-stage {
  width: 100%;
  justify-content: center;
  padding: 10px 16px;
  background: transparent;
  border: 1px solid var(--stage-color);
  color: var(--stage-color);
  font-size: 13px;
  font-weight: 500;
}
.btn-stage:hover {
  background: color-mix(in oklab, var(--stage-color) 12%, transparent);
}
.btn-stage-filled {
  background: var(--stage-color);
  color: var(--bg-base);
  border-color: var(--stage-color);
  font-weight: 600;
}
.btn-stage-filled:hover {
  filter: brightness(1.08);
}

/* ============================================================
   Dashboard cards
   ============================================================ */
.dash-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.dash-card {
  --stage-color: var(--accent);
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-card);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  position: relative;
  transition: border-color 150ms ease, transform 150ms ease, background 150ms ease;
  cursor: pointer;
  min-height: 320px;
}
.dash-card:hover {
  border-color: var(--border-active);
  background: var(--bg-elevated);
  transform: translateY(-1px);
}
.dash-card.running::before {
  content: "";
  position: absolute;
  top: -1px;
  left: -1px;
  right: -1px;
  height: 2px;
  background: var(--warning);
  border-radius: var(--r-card) var(--r-card) 0 0;
  animation: pulse-bar 1.5s ease-in-out infinite;
}
@keyframes pulse-bar {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}
.dash-card-header {
  display: flex;
  align-items: center;
  gap: 10px;
}
.dash-card-icon {
  width: 32px;
  height: 32px;
  border-radius: var(--r-avatar);
  background: color-mix(in oklab, var(--stage-color) 16%, transparent);
  color: var(--stage-color);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.dash-card-name {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-secondary);
  font-weight: 500;
  flex: 1;
}
.dash-card-title-row { margin-bottom: 4px; }
.dash-card-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0;
}
.dash-card-open {
  color: var(--text-muted);
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
}
.dash-card:hover .dash-card-open { color: var(--text-primary); }

.activity-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
}
.activity-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  color: var(--text-primary);
  line-height: 1.4;
}
.activity-text {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.activity-time {
  font-size: 11px;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}
.topic-pill {
  display: inline-block;
  padding: 2px 8px;
  border-radius: var(--r-pill);
  background: color-mix(in oklab, var(--stage-color) 14%, transparent);
  color: var(--stage-color);
  font-size: 11px;
  font-family: var(--font-mono);
  margin-right: 6px;
}
.source-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: var(--r-pill);
  background: var(--bg-elevated);
  color: var(--text-secondary);
  font-size: 11px;
  font-family: var(--font-mono);
  flex-shrink: 0;
}
.relevance-bar {
  width: 48px;
  height: 4px;
  border-radius: 2px;
  background: var(--bg-elevated);
  overflow: hidden;
  flex-shrink: 0;
}
.relevance-bar-fill {
  height: 100%;
  background: var(--stage-color);
  border-radius: 2px;
}
.status-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: var(--r-pill);
  background: var(--bg-elevated);
  color: var(--text-secondary);
  font-size: 11px;
  font-family: var(--font-mono);
  flex-shrink: 0;
}
.status-chip.in-progress {
  background: color-mix(in oklab, var(--warning) 16%, transparent);
  color: var(--warning);
}

/* ============================================================
   Stage workspace
   ============================================================ */
.stage-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
}
.stage-header-left {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}
.back-btn {
  width: 32px;
  height: 32px;
  border-radius: var(--r-button);
  background: var(--bg-surface);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  display: grid;
  place-items: center;
  flex-shrink: 0;
  margin-top: 2px;
}
.back-btn:hover { background: var(--bg-elevated); color: var(--text-primary); }
.stage-title-block {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.stage-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 20px;
  font-weight: 600;
  color: var(--stage-color);
  margin: 0;
}
.stage-desc { color: var(--text-secondary); margin: 0; font-size: 14px; }

.stage-split {
  display: grid;
  grid-template-columns: 40% 1fr;
  gap: 20px;
  height: calc(100vh - 200px);
  min-height: 540px;
}

/* Input zone */
.input-zone {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-card);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow-y: auto;
}
.field-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: 8px;
  display: block;
}
.prompt-area {
  position: relative;
}
.prompt-textarea {
  width: 100%;
  min-height: 120px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-input);
  color: var(--text-primary);
  font-family: var(--font-ui);
  font-size: 14px;
  padding: 12px 14px;
  resize: vertical;
  transition: border-color 100ms ease, box-shadow 100ms ease;
}
.prompt-textarea::placeholder { color: var(--text-muted); }
.prompt-textarea:focus {
  border-color: var(--stage-color);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--stage-color) 20%, transparent);
  outline: none;
}
.char-count {
  position: absolute;
  bottom: 8px;
  right: 12px;
  font-size: 11px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  pointer-events: none;
}

.drop-zone {
  background: var(--bg-elevated);
  border: 1.5px dashed var(--border);
  border-radius: var(--r-input);
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  color: var(--text-secondary);
  transition: border-color 100ms ease, background 100ms ease;
  text-align: center;
}
.drop-zone:hover {
  border-color: var(--border-active);
  background: var(--bg-elevated-hover);
}
.drop-zone-text { font-size: 13px; color: var(--text-primary); }
.drop-zone-sub { font-size: 12px; color: var(--text-muted); }
.format-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.format-pill {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-muted);
  padding: 2px 6px;
  background: var(--bg-base);
  border-radius: var(--r-pill);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.file-chip, .url-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-active);
  color: var(--text-primary);
  padding: 6px 8px 6px 10px;
  border-radius: var(--r-pill);
  font-size: 12px;
  margin-right: 6px;
  margin-top: 6px;
}
.file-chip-icon { color: var(--stage-color); display: grid; place-items: center; }
.chip-close {
  background: transparent;
  border: none;
  color: var(--text-muted);
  width: 18px;
  height: 18px;
  border-radius: 4px;
  display: grid;
  place-items: center;
  padding: 0;
}
.chip-close:hover { background: var(--border); color: var(--text-primary); }

.url-input-row {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-input);
  padding: 0 12px;
}
.url-input-row:focus-within {
  border-color: var(--stage-color);
}
.url-input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--text-primary);
  font-family: var(--font-ui);
  font-size: 13px;
  padding: 10px 0;
  outline: none;
}
.url-input::placeholder { color: var(--text-muted); }

.run-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 16px;
  background: var(--stage-color);
  color: var(--bg-base);
  border: none;
  border-radius: var(--r-button);
  font-size: 14px;
  font-weight: 600;
  margin-top: auto;
  transition: filter 80ms ease;
  box-shadow: 0 0 0 0 var(--stage-color);
}
.run-btn:hover { filter: brightness(1.08); }
.run-btn.loading {
  background: var(--bg-elevated);
  color: var(--text-secondary);
  cursor: progress;
}
.run-btn.done {
  background: transparent;
  color: var(--success);
  border: 1px solid var(--success);
}

/* Output zone */
.output-zone {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-card);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.output-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 20px;
  border-bottom: 1px solid var(--border);
  font-size: 12px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  flex-shrink: 0;
}
.output-meta-actions { display: flex; gap: 4px; }
.output-body {
  padding: 24px 28px;
  overflow-y: auto;
  flex: 1;
}
.output-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  color: var(--text-muted);
  padding: 40px;
  text-align: center;
}
.output-empty-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--bg-elevated);
  display: grid;
  place-items: center;
  color: var(--text-muted);
}

/* Markdown */
.md h1, .md h2, .md h3, .md h4 {
  color: var(--text-primary);
  font-weight: 600;
  margin: 24px 0 12px;
  letter-spacing: -0.01em;
}
.md h1 { font-size: 22px; margin-top: 0; }
.md h2 { font-size: 18px; }
.md h3 { font-size: 15px; }
.md p { color: var(--text-primary); margin: 0 0 14px; line-height: 1.65; }
.md ul, .md ol { padding-left: 22px; margin: 0 0 14px; }
.md li { margin-bottom: 6px; line-height: 1.65; }
.md li::marker { color: var(--text-muted); }
.md strong { color: var(--text-primary); font-weight: 600; }
.md em { color: var(--text-secondary); }
.md code {
  font-family: var(--font-mono);
  font-size: 12.5px;
  background: var(--bg-elevated);
  padding: 1.5px 5px;
  border-radius: 3px;
  color: var(--stage-color);
}
.md pre {
  font-family: var(--font-mono);
  font-size: 13px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-input);
  padding: 14px 16px;
  overflow-x: auto;
  margin: 0 0 16px;
  line-height: 1.55;
}
.md pre code { background: transparent; padding: 0; color: var(--text-primary); }
.md blockquote {
  border-left: 2px solid var(--stage-color);
  padding-left: 14px;
  margin: 0 0 16px;
  color: var(--text-secondary);
  font-style: normal;
}
.md a { color: var(--accent); text-decoration: none; border-bottom: 1px dashed var(--accent-glow); }
.md a:hover { border-bottom-style: solid; }
.md hr { border: none; border-top: 1px solid var(--border); margin: 24px 0; }

/* Hook cards (Hooks workspace) */
.hook-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-input);
  padding: 16px 18px;
  margin-bottom: 12px;
  display: flex;
  gap: 14px;
  transition: border-color 100ms ease;
}
.hook-card:hover { border-color: var(--border-active); }
.hook-num {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: var(--stage-color);
  background: color-mix(in oklab, var(--stage-color) 16%, transparent);
  width: 24px;
  height: 24px;
  border-radius: var(--r-pill);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.hook-body { flex: 1; }
.hook-text { color: var(--text-primary); font-size: 14px; line-height: 1.55; margin: 0 0 8px; }
.hook-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  color: var(--text-muted);
  font-family: var(--font-mono);
}
.hook-score {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--stage-color);
}

/* Skeleton loaders */
.skeleton {
  background: linear-gradient(90deg, var(--bg-elevated) 0%, var(--bg-elevated-hover) 40%, var(--bg-elevated) 80%);
  background-size: 200% 100%;
  animation: shimmer 1.2s ease-in-out infinite;
  border-radius: 4px;
}
@keyframes shimmer {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}
.skeleton-row { height: 14px; margin-bottom: 12px; }
.skeleton-row.short { width: 60%; }
.skeleton-row.medium { width: 80%; }
.skeleton-row.long { width: 100%; }
.skeleton-block { height: 80px; margin-bottom: 14px; }

/* Non-dashboard workspaces — centered, narrower column for focus */
[data-screen-label]:not([data-screen-label="Dashboard"]) {
  max-width: 1080px;
  margin: 0 auto;
}

/* ============================================================
   History drawer (always peeking, hover to expand)
   ============================================================ */
.drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.4);
  z-index: 900;
  opacity: 0;
  transition: opacity 150ms ease;
  pointer-events: none;
}
.drawer-backdrop.open { opacity: 1; pointer-events: auto; }
.drawer {
  position: fixed;
  top: 24px;
  right: 0;
  height: calc(100vh - 48px);
  width: 380px;
  background:
    radial-gradient(80% 100% at 100% 0%,
      color-mix(in oklab, var(--page-accent) 22%, transparent) 0%,
      transparent 60%),
    radial-gradient(60% 80% at 0% 100%,
      color-mix(in oklab, var(--page-accent) 14%, transparent) 0%,
      transparent 55%),
    color-mix(in oklab, var(--bg-surface) 88%, transparent);
  backdrop-filter: blur(20px) saturate(140%);
  -webkit-backdrop-filter: blur(20px) saturate(140%);
  border: 1px solid color-mix(in oklab, var(--page-accent) 32%, var(--border));
  border-right: none;
  border-radius: 14px 0 0 14px;
  transform: translateX(calc(100% - 54px));
  opacity: 0.85;
  transition:
    transform 360ms cubic-bezier(0.2, 0.7, 0.2, 1),
    opacity 280ms ease,
    box-shadow 280ms ease,
    border-color 280ms ease;
  z-index: 901;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  will-change: transform;
}
.drawer:hover,
.drawer.open {
  transform: translateX(0);
  opacity: 1;
  border-color: color-mix(in oklab, var(--page-accent) 55%, var(--border));
  box-shadow:
    -24px 0 64px -20px rgba(0, 0, 0, 0.7),
    0 0 40px -16px color-mix(in oklab, var(--page-accent) 50%, transparent);
}

/* Subtle animated dot pattern — ties drawer to the global particle field */
.drawer::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(
    circle,
    color-mix(in oklab, var(--page-accent) 40%, transparent) 1px,
    transparent 1.6px
  );
  background-size: 28px 28px;
  opacity: 0.16;
  pointer-events: none;
  z-index: 0;
  animation: drawerDrift 80s linear infinite;
}
@keyframes drawerDrift {
  from { background-position: 0 0; }
  to   { background-position: 56px 56px; }
}

/* Vertical handle — visible in the peek state, fades when open */
.drawer-handle {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 54px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: 24px 0;
  gap: 16px;
  pointer-events: none;
  z-index: 2;
  transition: opacity 220ms ease;
}
.drawer-handle svg {
  color: var(--page-accent);
  filter: drop-shadow(0 0 6px color-mix(in oklab, var(--page-accent) 60%, transparent));
}
.drawer-handle-text {
  writing-mode: vertical-rl;
  text-orientation: mixed;
  transform: rotate(180deg);
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.34em;
  color: var(--page-accent);
  text-transform: uppercase;
  font-weight: 500;
}
.drawer-handle-count {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--page-accent);
  background: color-mix(in oklab, var(--page-accent) 14%, transparent);
  padding: 2px 7px;
  border-radius: var(--r-pill);
  border: 1px solid color-mix(in oklab, var(--page-accent) 26%, var(--border));
  margin-top: auto;
}
.drawer:hover .drawer-handle,
.drawer.open .drawer-handle { opacity: 0; }

/* Drawer content sits to the right of the handle */
.drawer-content {
  position: relative;
  z-index: 1;
  padding-left: 54px;
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}
.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 20px 20px 6px;
  border-bottom: 1px solid color-mix(in oklab, var(--page-accent) 20%, var(--border));
}
.drawer-title {
  font-size: 14px;
  font-weight: 600;
  margin: 0;
  color: var(--text-primary);
}
.drawer-eyebrow {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--page-accent);
  margin-bottom: 4px;
}
.drawer-body {
  padding: 12px 14px 12px 6px;
  overflow-y: auto;
  flex: 1;
  min-height: 0;
}
.history-item {
  padding: 12px;
  border-radius: var(--r-button);
  cursor: pointer;
  transition: background 100ms ease, border-color 100ms ease, transform 180ms cubic-bezier(0.2,0.7,0.2,1);
  border: 1px solid transparent;
}
.history-item:hover {
  background: color-mix(in oklab, var(--page-accent) 8%, var(--bg-elevated));
  border-color: color-mix(in oklab, var(--page-accent) 30%, var(--border));
  transform: translateX(2px);
}
.history-time {
  font-size: 11px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  margin-bottom: 4px;
}
.history-prompt { font-size: 13px; color: var(--text-primary); margin-bottom: 4px; line-height: 1.4; }
.history-stat { font-size: 11px; color: var(--text-secondary); font-family: var(--font-mono); }

/* ============================================================
   Knowledge Brain
   ============================================================ */
.brain-input-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-card);
  padding: 20px;
  margin-bottom: 24px;
}
.brain-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
}
.brain-toolbar .btn-stage {
  width: auto;
}
.brain-toolbar .run-btn {
  margin-top: 0;
  margin-left: auto;
  width: auto;
  padding: 10px 18px;
}

.score-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 28px;
}
.score-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-card);
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
}
.score-arc {
  width: 72px;
  height: 72px;
  flex-shrink: 0;
  position: relative;
}
.score-arc svg { width: 100%; height: 100%; transform: rotate(-90deg); }
.score-arc-track { fill: none; stroke: var(--bg-elevated); stroke-width: 6; }
.score-arc-fill { fill: none; stroke: var(--brain); stroke-width: 6; stroke-linecap: round; }
.score-arc-value {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
}
.score-meta { display: flex; flex-direction: column; gap: 2px; }
.score-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
}
.score-value {
  font-family: var(--font-mono);
  font-size: 22px;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.1;
}
.score-sub {
  font-size: 11px;
  color: var(--text-muted);
  font-family: var(--font-mono);
}

.analysis-section {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-card);
  margin-bottom: 12px;
  overflow: hidden;
}
.analysis-section-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: transparent;
  border: none;
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 600;
}
.analysis-section-header:hover { background: var(--bg-elevated); }
.analysis-section-num {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--brain);
  margin-right: 12px;
  font-weight: 500;
}
.analysis-section-chevron {
  color: var(--text-muted);
  transition: transform 200ms ease;
}
.analysis-section.open .analysis-section-chevron {
  transform: rotate(180deg);
}
.analysis-section-body {
  padding: 4px 20px 20px;
  border-top: 1px solid var(--border);
}
.trigger-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
}
.trigger-chip {
  padding: 6px 12px;
  background: color-mix(in oklab, var(--brain) 14%, transparent);
  color: var(--brain);
  border-radius: var(--r-pill);
  font-size: 12px;
  font-family: var(--font-mono);
  border: 1px solid color-mix(in oklab, var(--brain) 24%, transparent);
}
.structure-step {
  display: flex;
  gap: 14px;
  padding: 10px 0;
  border-bottom: 1px dashed var(--border);
}
.structure-step:last-child { border-bottom: none; }
.structure-step-num {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--brain);
  width: 32px;
  flex-shrink: 0;
}
.structure-step-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0 0 4px;
}
.structure-step-desc { font-size: 12px; color: var(--text-secondary); margin: 0; }
.structure-step-timer {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-muted);
  margin-left: auto;
  flex-shrink: 0;
}

.brain-header-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--r-avatar);
  background: color-mix(in oklab, var(--brain) 16%, transparent);
  color: var(--brain);
  display: grid;
  place-items: center;
  margin-right: 4px;
}

/* ============================================================
   Mode toggle — Fast / Deep Research switch in InputZone
   ============================================================ */
.mode-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 4px;
}
.mode-toggle-row-label {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-muted);
  font-weight: 500;
}
.mode-toggle {
  --mode-padding: 4px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  position: relative;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: var(--mode-padding);
  user-select: none;
  transition: border-color 200ms ease, box-shadow 240ms ease;
}
.mode-toggle:hover {
  border-color: color-mix(in oklab, var(--stage-color) 35%, var(--border));
}
.mode-toggle-slider {
  position: absolute;
  top: var(--mode-padding);
  left: var(--mode-padding);
  width: calc(50% - var(--mode-padding));
  height: calc(100% - var(--mode-padding) * 2);
  background:
    radial-gradient(60% 100% at 50% 100%,
      color-mix(in oklab, var(--stage-color) 28%, transparent) 0%,
      transparent 70%),
    var(--stage-color);
  border-radius: 999px;
  box-shadow:
    0 4px 12px -4px color-mix(in oklab, var(--stage-color) 60%, transparent),
    inset 0 1px 0 0 color-mix(in oklab, white 20%, transparent);
  transition: transform 320ms cubic-bezier(0.34, 1.3, 0.4, 1);
  z-index: 1;
}
.mode-toggle[data-mode="deep"] .mode-toggle-slider {
  transform: translateX(100%);
}
.mode-toggle-option {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 7px 10px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  background: transparent;
  border: none;
  border-radius: 999px;
  font-family: inherit;
  transition: color 200ms ease, transform 200ms cubic-bezier(0.2,0.7,0.2,1);
  white-space: nowrap;
}
.mode-toggle-option svg {
  transition: transform 240ms cubic-bezier(0.2,0.7,0.2,1);
}
.mode-toggle-option:hover:not(.is-active) {
  color: var(--text-primary);
}
.mode-toggle-option.is-active {
  color: #0a1226;
  font-weight: 600;
}
.mode-toggle-option.is-active svg {
  transform: scale(1.08);
}
.mode-toggle-meta {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-muted);
  letter-spacing: 0.04em;
  margin-top: 6px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.mode-toggle-meta-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--stage-color);
  box-shadow: 0 0 6px var(--stage-color);
  flex-shrink: 0;
}

/* ============================================================
   Stacked panel — two cards layered; click the back to swap
   ============================================================ */

/* Brain workspace uses a non-split stacked panel — give it a fixed height
   so the absolutely-positioned faces have something to fill. */
.brain-stack {
  position: relative;
  min-height: 700px;
}
.brain-stack .stacked-panel {
  position: relative;
  height: auto;
  min-height: 700px;
}
.brain-stack-face {
  background: var(--bg-base);
  border-radius: var(--r-card);
  padding: 0;
  height: 100%;
  overflow-y: auto;
}

.stacked-panel {
  position: relative;
  min-height: 0;
  height: 100%;
  /* room for the back peek + bookmark */
  padding-right: 52px;
  padding-bottom: 18px;
}
.stacked-face {
  position: absolute;
  inset: 0;
  border-radius: var(--r-card);
  transition:
    transform 420ms cubic-bezier(0.2, 0.7, 0.2, 1),
    opacity   420ms ease,
    filter    420ms ease,
    box-shadow 420ms ease;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.stacked-face > * {
  flex: 1;
  min-height: 0;
  height: 100%;
}
.stacked-face.is-front {
  transform: translate(0, 0);
  z-index: 3;
  opacity: 1;
  filter: none;
  box-shadow: 0 12px 32px -18px rgba(0, 0, 0, 0.6);
}
.stacked-face.is-back {
  transform: translate(44px, 18px) scale(0.996);
  z-index: 2;
  opacity: 0.72;
  filter: brightness(0.82) saturate(0.9);
  cursor: pointer;
}
.stacked-face.is-back:hover {
  transform: translate(40px, 14px) scale(1);
  opacity: 0.95;
  filter: brightness(0.96) saturate(1);
}
/* Make the entire back face clickable but block clicks on its inner controls */
.stacked-face.is-back > * { pointer-events: none; }
.stacked-face.is-back::after { display: none; }

/* ============================================================
   Sources / Vault panel (the back card)
   ============================================================ */
.sources-panel {
  position: relative;
  background:
    radial-gradient(60% 80% at 100% 0%,
      color-mix(in oklab, var(--page-accent) 16%, transparent) 0%,
      transparent 60%),
    radial-gradient(50% 80% at 0% 100%,
      color-mix(in oklab, var(--page-accent) 10%, transparent) 0%,
      transparent 55%),
    var(--bg-surface);
  border: 1px solid color-mix(in oklab, var(--page-accent) 22%, var(--border));
  border-radius: var(--r-card);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  height: 100%;
}
.sources-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 60px 12px 20px;
  border-bottom: 1px solid color-mix(in oklab, var(--page-accent) 18%, var(--border));
  font-size: 12px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  flex-shrink: 0;
}
.sources-meta-left {
  display: flex;
  align-items: center;
  gap: 10px;
}
.sources-meta-eyebrow {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--page-accent);
  font-weight: 500;
}
.sources-body {
  padding: 16px 60px 20px 18px;
  overflow-y: auto;
  flex: 1;
  min-height: 0;
}

/* ----- Vault bookmark (always-visible tab on the right edge) ----- */
.vault-bookmark {
  position: absolute;
  top: 36px;
  right: 0;
  width: 44px;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 14px 0;
  gap: 12px;
  background:
    linear-gradient(180deg,
      color-mix(in oklab, var(--page-accent) 26%, var(--bg-elevated)) 0%,
      color-mix(in oklab, var(--page-accent) 14%, var(--bg-elevated)) 100%);
  border: 1px solid color-mix(in oklab, var(--page-accent) 38%, var(--border));
  border-right: none;
  border-radius: 10px 0 0 10px;
  color: var(--page-accent);
  box-shadow: -4px 6px 16px -10px rgba(0, 0, 0, 0.6);
  z-index: 5;
  pointer-events: none;
  transition:
    background 280ms ease,
    border-color 280ms ease,
    box-shadow 280ms ease;
}
.vault-bookmark-icon {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: color-mix(in oklab, var(--page-accent) 18%, transparent);
  border: 1px solid color-mix(in oklab, var(--page-accent) 32%, transparent);
  color: var(--page-accent);
  filter: drop-shadow(0 0 6px color-mix(in oklab, var(--page-accent) 60%, transparent));
}
.vault-bookmark-text {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.36em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--page-accent);
  white-space: nowrap;
  text-shadow: 0 0 8px color-mix(in oklab, var(--page-accent) 50%, transparent);
}
.vault-bookmark-count {
  font-family: var(--font-mono);
  font-size: 10px;
  padding: 2px 7px;
  background: color-mix(in oklab, var(--page-accent) 18%, transparent);
  border: 1px solid color-mix(in oklab, var(--page-accent) 32%, var(--border));
  border-radius: 999px;
  color: var(--page-accent);
  letter-spacing: 0;
  margin-top: auto;
}

/* When the panel is the back card, brighten the bookmark so it reads as the affordance */
.stacked-face.is-back .vault-bookmark {
  background:
    linear-gradient(180deg,
      color-mix(in oklab, var(--page-accent) 38%, var(--bg-elevated)) 0%,
      color-mix(in oklab, var(--page-accent) 22%, var(--bg-elevated)) 100%);
  border-color: color-mix(in oklab, var(--page-accent) 56%, var(--border));
  box-shadow:
    -6px 8px 22px -10px rgba(0, 0, 0, 0.65),
    0 0 20px -6px color-mix(in oklab, var(--page-accent) 45%, transparent);
}
.stacked-face.is-back:hover .vault-bookmark {
  background:
    linear-gradient(180deg,
      color-mix(in oklab, var(--page-accent) 50%, var(--bg-elevated)) 0%,
      color-mix(in oklab, var(--page-accent) 30%, var(--bg-elevated)) 100%);
  border-color: color-mix(in oklab, var(--page-accent) 70%, var(--border));
}
.sources-section + .sources-section { margin-top: 22px; }
.sources-section-title {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  font-weight: 600;
  margin: 0 0 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.sources-section-count {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--page-accent);
  background: color-mix(in oklab, var(--page-accent) 14%, transparent);
  padding: 2px 6px;
  border-radius: var(--r-pill);
  letter-spacing: 0;
}

/* Folder tree */
.tree {
  display: flex;
  flex-direction: column;
  font-family: var(--font-mono);
  font-size: 12.5px;
}
.tree-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 8px 5px 6px;
  border-radius: 4px;
  color: var(--text-primary);
  cursor: default;
  position: relative;
  transition: background 120ms ease, color 120ms ease, padding-left 200ms cubic-bezier(0.2,0.7,0.2,1);
}
.tree-row:hover {
  background: color-mix(in oklab, var(--page-accent) 10%, transparent);
  color: var(--page-accent);
  padding-left: 10px;
}
.tree-row.is-current {
  color: var(--page-accent);
  font-weight: 500;
}
.tree-row.is-current::before {
  content: "";
  position: absolute;
  left: 0;
  top: 6px;
  bottom: 6px;
  width: 2px;
  border-radius: 2px;
  background: var(--page-accent);
}
.tree-indent { width: 16px; flex-shrink: 0; }
.tree-icon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  color: var(--text-muted);
  display: grid;
  place-items: center;
}
.tree-row:hover .tree-icon,
.tree-row.is-current .tree-icon { color: var(--page-accent); }
.tree-name {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tree-meta {
  font-size: 10.5px;
  color: var(--text-muted);
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
.tree-row.is-folder { color: var(--text-secondary); font-weight: 500; }

/* Source link rows (URLs cited by this run) */
.source-link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg-elevated);
  margin-bottom: 8px;
  cursor: pointer;
  transition: border-color 150ms ease, background 150ms ease, transform 200ms cubic-bezier(0.2,0.7,0.2,1);
  text-align: left;
  width: 100%;
  font-family: inherit;
  font-size: inherit;
  color: inherit;
}
.source-link:hover {
  border-color: color-mix(in oklab, var(--page-accent) 40%, var(--border));
  background: color-mix(in oklab, var(--page-accent) 6%, var(--bg-elevated));
  transform: translateX(2px);
}
.tree-row.is-clickable { cursor: pointer; }

/* In-panel file viewer */
.viewer-toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 20px;
  border-bottom: 1px solid color-mix(in oklab, var(--page-accent) 18%, var(--border));
  flex-shrink: 0;
  background: color-mix(in oklab, var(--page-accent) 4%, transparent);
}
.viewer-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: var(--r-button);
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-secondary);
  font-size: 12px;
  font-family: var(--font-ui);
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease, transform 200ms cubic-bezier(0.2,0.7,0.2,1);
}
.viewer-back:hover {
  background: var(--bg-elevated);
  color: var(--text-primary);
  transform: translateX(-2px);
}
.viewer-path {
  flex: 1;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.viewer-path-name {
  color: var(--page-accent);
  font-weight: 500;
}
.viewer-meta-pill {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 4px 8px;
  border-radius: var(--r-pill);
  background: color-mix(in oklab, var(--page-accent) 14%, transparent);
  color: var(--page-accent);
  border: 1px solid color-mix(in oklab, var(--page-accent) 28%, var(--border));
  flex-shrink: 0;
}
.viewer-actions { display: flex; gap: 6px; }
.viewer-body {
  padding: 24px 28px;
  overflow-y: auto;
  flex: 1;
  min-height: 0;
}
.viewer-empty-meta {

