file.content:
.slide {
  position: absolute;
  inset: 0;
  padding: 2.8rem 5rem 2.5rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  opacity: 0;
  transform: translateX(56px);
  transition: opacity 0.42s cubic-bezier(0.16,1,0.3,1),
              transform 0.42s cubic-bezier(0.16,1,0.3,1);
  pointer-events: none;
  overflow-y: auto;
}
.slide.active { opacity: 1; transform: translateX(0); pointer-events: all; }
.slide.exit   { opacity: 0; transform: translateX(-56px); }

.ghost {
  position: absolute;
  right: 3rem; bottom: 1rem;
  font-family: 'Cormorant Garamond', serif;
  font-size: 18vw; font-weight: 300; line-height: 1;
  color: var(--text); opacity: 0.03;
  pointer-events: none; user-select: none;
  letter-spacing: -0.04em;
}

/* ── Section label + headings ── */
.label {
  font-family: 'DM Mono', monospace;
  font-size: 0.72rem; letter-spacing: 0.16em; text-transform: uppercase;
  color: var(--text-muted); margin-bottom: 0.75rem;
  display: flex; align-items: center; gap: 0.75rem;
}
.label::before { content:''; display:block; width:2rem; height:1px; background:var(--accent); }

.title {
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(2.6rem, 4.5vw, 3.8rem); font-weight: 300;
  line-height: 1.05; letter-spacing: -0.02em; margin-bottom: 0.3rem;
}
.title em { font-style: italic; color: var(--accent); }

.sub {
  font-family: 'DM Mono', monospace;
  font-size: 0.82rem; color: var(--text-muted);
  letter-spacing: 0.05em; margin-bottom: 1.75rem;
}

/* ═══════════════════════════
   SLIDE 1 — COVER
═══════════════════════════ */
#s1 {
  background: radial-gradient(ellipse 55% 55% at 72% 50%, rgba(232,149,109,0.05) 0%, transparent 70%), var(--bg);
