.cn-block { display: flex; flex-direction: column; }
.cn {
  background: var(--surface); border: 1px solid var(--border);
  padding: 1rem 1.25rem;
}
.cn + .cn { border-top: none; }
.cn:first-child { border-radius: 4px 4px 0 0; }
.cn:last-child  { border-radius: 0 0 4px 4px; }
.cn.p1 { border-left: 2px solid var(--accent); }
.cn.p2 { border-left: 2px solid var(--blue); }
.cn.p3 { border-left: 2px solid var(--green); }
.cn .cn-lbl { font-family:'DM Mono',monospace; font-size:0.7rem; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.1em; margin-bottom:0.25rem; }
.cn .cn-name { font-family:'Cormorant Garamond',serif; font-size:1.55rem; font-weight:400; line-height:1; }
.cn .cn-note { font-family:'DM Mono',monospace; font-size:0.7rem; color:var(--text-dim); margin-top:0.2rem; }

.cascade-mid {
  display:flex; align-items:center; justify-content:center;
  font-family:'DM Mono',monospace; font-size:0.7rem; color:var(--text-dim);
  writing-mode:vertical-rl; padding: 0 0.5rem; align-self:center;
}

.wcard-list { display:flex; flex-direction:column; gap:0.75rem; }
.wcard {
  background: var(--surface); border: 1px solid var(--border); border-radius:4px; padding:1rem 1.25rem;
}
.wcard .wt { font-family:'DM Mono',monospace; font-size:0.82rem; color:var(--accent); margin-bottom:0.35rem; }
.wcard .wd { font-size:0.9rem; color:var(--text-muted); line-height:1.6; }
.wcard.dropped { border-left:2px solid var(--red); opacity:0.5; }
.wcard.dropped .wt { color:var(--red); }

/* ═══════════════════════════
   SLIDE 6 — GUARDRAILS
═══════════════════════════ */
.gr-grid {
  display:grid; grid-template-columns:repeat(3,1fr); gap:1rem; max-width:940px;
}
.grc {
  background:var(--surface); border:1px solid var(--border); border-radius:4px;
  padding:1.3rem 1.2rem; display:flex; flex-direction:column; gap:0.75rem;
}
.gr-badge {
  width:2.2rem; height:2.2rem; border-radius:50%;
  display:flex; align-items:center; justify-content:center;
  font-family:'DM Mono',monospace; font-size:0.78rem; font-weight:500;
}
.grc.ga .gr-badge { background:var(--amber-dim); color:var(--amber); }
.grc.gg .gr-badge { background:var(--green-dim); color:var(--green); }
.grc.gb .gr-badge { background:var(--blue-dim); color:var(--blue); }
.gr-title { font-family:'Cormorant Garamond',serif; font-size:1.3rem; font-weight:400; line-height:1.2; }
.gr-file  { font-family:'DM Mono',monospace; font-size:0.7rem; color:var(--text-dim); }
.gr-items { list-style:none; display:flex; flex-direction:column; gap:0.4rem; }
.gr-items li { font-family:'DM Mono',monospace; font-size:0.75rem; color:var(--text-muted); display:flex; gap:0.5rem; line-height:1.5; }
.gr-items li::before { content:'→'; flex-shrink:0; opacity:0.45; }
.pill-row { display:flex; flex-wrap:wrap; gap:0.4rem; margin-top:0.2rem; }
.pill { font-family:'DM Mono',monospace; font-size:0.7rem; padding:0.22rem 0.55rem; border-radius:3px; }
.pill.ok  { background:var(--green-dim); color:var(--green); }
.pill.no  { background:var(--red-dim); color:var(--red); }
.pill.neu { background:var(--surface-2); color:var(--text-muted); border:1px solid var(--border); }

/* ═══════════════════════════
   SLIDE 7 — BLOCKING GATES
═══════════════════════════ */
.gate-list { display:flex; flex-direction:column; gap:1rem; max-width:820px; }
.gate {
  display:grid; grid-template-columns:130px 1fr;
  border:1px solid var(--border); border-radius:4px; overflow:hidden;
}
.gate-cmd {
  background:var(--red-dim); border-right:2px solid var(--red);
  padding:1.25rem 1rem; display:flex; flex-direction:column; justify-content:center; gap:0.25rem;
}
.gate-cmd .gc { font-family:'DM Mono',monospace; font-size:0.9rem; color:var(--red); }
.gate-cmd .gt { font-family:'DM Mono',monospace; font-size:0.65rem; color:var(--red); opacity:0.6; text-transform:uppercase; letter-spacing:0.1em; }
.gate-body { background:var(--surface); padding:1.25rem 1.6rem; }
.gate-q { font-family:'Cormorant Garamond',serif; font-size:1.25rem; font-style:italic; margin-bottom:0.4rem; line-height:1.4; }
.gate-r { font-family:'DM Mono',monospace; font-size:0.76rem; color:var(--text-muted); line-height:1.55; }

/* ═══════════════════════════
   SLIDE 8 — EVAL SYSTEM
═══════════════════════════ */
.eval-layout { display:grid; grid-template-columns:1fr 1fr; gap:2.5rem; max-width:880px; }
.eval-node {
  background:var(--surface); border:1px solid var(--border);
  border-left:2px solid var(--blue); border-radius:0 4px 4px 0; padding:0.9rem 1.1rem;
}
.eval-node .en { font-family:'DM Mono',monospace; font-size:0.78rem; color:var(--blue); margin-bottom:0.3rem; }
.eval-node .ed { font-size:0.88rem; color:var(--text-muted); line-height:1.6; }
.connector { display:flex; align-items:center; justify-content:center; height:1.6rem; }
.connector::after { content:'↓'; font-family:'DM Mono',monospace; font-size:0.75rem; color:var(--text-dim); }
.cov-list { display:flex; flex-direction:column; gap:0.45rem; }
.cov-item {
  display:grid; grid-template-columns:1fr auto; gap:1rem;
  padding:0.55rem 0.85rem; background:var(--surface);
  border:1px solid var(--border); border-radius:4px;
  font-family:'DM Mono',monospace; font-size:0.78rem;
}
.cov-item .cn { color:var(--text); }
.cov-item .cc { color:var(--blue); }

/* ═══════════════════════════
   SLIDE 9 — VAULT
═══════════════════════════ */
.vault-layout { display:grid; grid-template-columns:1fr 1fr; gap:3rem; max-width:900px; align-items:start; }
.tree { font-family:'DM Mono',monospace; font-size:0.82rem; line-height:2.0; color:var(--text-muted); }
.tree .tr { color:var(--text); font-size:0.88rem; }
.tree .hi { color:var(--accent); }
.tree .pe { color:var(--amber); }
.tree .cm { color:var(--text-dim); margin-left:0.5rem; font-size:0.72rem; }
.vault-notes { display:flex; flex-direction:column; gap:1rem; }
.vn-item { display:flex; gap:0.75rem; align-items:flex-start; }
.vn-dot { width:0.5rem; height:0.5rem; border-radius:50%; flex-shrink:0; margin-top:0.35rem; }
.vn-label { font-family:'DM Mono',monospace; font-size:0.78rem; color:var(--text); margin-bottom:0.2rem; }
.vn-desc  { font-size:0.88rem; color:var(--text-muted); line-height:1.6; }

