835	<script>
836	  const slides = Array.from(document.querySelectorAll('.slide'));
837	  const total  = slides.length;
838	  let cur = 0;
839	
840	  function go(n) {
841	    if (n < 0 || n >= total) return;
842	    slides[cur].classList.remove('active');
843	    slides[cur].classList.add('exit');
844	    const old = cur;
845	    setTimeout(() => slides[old].classList.remove('exit'), 480);
846	    cur = n;
847	    slides[cur].classList.add('active');
848	    document.getElementById('counter').textContent =
849	      String(cur+1).padStart(2,'0') + ' / ' + String(total).padStart(2,'0');
850	    document.getElementById('prog').style.width = ((cur+1)/total*100) + '%';
851	    document.getElementById('prev').disabled = cur === 0;
852	    document.getElementById('next').disabled = cur === total-1;
853	  }
854	
855	  document.getElementById('prev').addEventListener('click', () => go(cur-1));
856	  document.getElementById('next').addEventListener('click', () => go(cur+1));
857	
858	  document.addEventListener('keydown', e => {
859	    if (e.key === 'ArrowRight' || e.key === ' ') { e.preventDefault(); go(cur+1); }
860	    if (e.key === 'ArrowLeft')                    { e.preventDefault(); go(cur-1); }
861	    if (e.key === 'Home')                          go(0);
862	    if (e.key === 'End')                           go(total-1);
863	  });
864	</script>
